<script lang="ts">
 import {goto} from '$app/navigation';import {page} from '$app/state';import {claimStore} from '../store';import {refresh} from '../app.svelte';import {DEMO_PASSWORD} from '../sample';import Icon from '../components/Icon.svelte';
